"""Cross-language contract fixtures generated by the real release publisher."""
from pathlib import Path
import json
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'scripts'))
import appcast
import release

output = Path(sys.argv[1])
output.mkdir(parents=True, exist_ok=True)
feeds = {arch: None for arch in release.ARCHITECTURES}
for version, build in [('0.1.0', '1'), ('0.2.0-alpha.2', '2'), ('0.2.0-alpha.10', '3')]:
    with tempfile.TemporaryDirectory() as directory:
        assets = Path(directory)
        for arch in release.ARCHITECTURES:
            (assets / release.asset_name(version, arch)).write_bytes(arch.encode())
        metadata = dict(tag_name='v'+version, html_url=appcast.REPOSITORY+'/releases/tag/v'+version,
            draft=False, prerelease='-' in version, published_at='2026-11-07T14:00:00Z',
            body='<!-- neylu:en -->\n### English\n\n- **Fix** & <data>\n<!-- neylu:zh-Hans -->\n中文更新',
            assets=[dict(name=p.name, size=p.stat().st_size, state='uploaded', digest='sha256:'+release.sha256_file(p),
                browser_download_url=appcast.REPOSITORY+'/releases/download/v'+version+'/'+p.name) for p in assets.iterdir()])
        for arch, item in appcast.candidate(metadata, assets, build).items():
            feeds[arch] = appcast.merge(feeds[arch], item, arch)
for arch, data in feeds.items():
    (output / f'appcast-{arch}.xml').write_bytes(data)
